/* ============================================================
   SINGH CREATIVE STUDIO — LIGHT EDITORIAL / BLOGGER RESPONSIVE
   Blogger mobile mode is enabled on the root html element.
   ============================================================ */
:root{color-scheme:light;--paper:#f8f9fc;--white:#fff;--ink:#171923;--muted:#626b7a;--violet:#7957ff;--blue:#4da8ff;--mint:#b7f7d8;--lav:#ede7ff;--line:rgba(23,25,35,.12);--mono:'DM Mono',monospace;--sans:'Space Grotesk',Arial,sans-serif;scroll-behavior:smooth;scroll-padding-top:85px}
*{box-sizing:border-box}html,body{width:100%;min-width:320px;max-width:100%;margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}body{overflow-x:hidden}button,input,select,textarea{font:inherit}button{color:inherit;cursor:pointer}a{color:inherit;text-decoration:none}img,video,canvas,iframe{max-width:100%}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--violet);outline-offset:3px}::selection{background:#d8ceff;color:#171923}[hidden]{display:none!important}
/* The story fully covers the Blogger page until the visitor chooses to enter. */
.storyboard{position:fixed;z-index:10000;inset:0;width:100%;height:100vh;height:100dvh;min-height:100svh;overflow:hidden;isolation:isolate;background:#f8f9fc;color:var(--ink);padding:env(safe-area-inset-top,0px) env(safe-area-inset-right,0px) env(safe-area-inset-bottom,0px) env(safe-area-inset-left,0px);transition:opacity .75s ease,transform .75s cubic-bezier(.2,.7,.2,1)}.storyboard.is-exiting{opacity:0;transform:scale(1.025);pointer-events:none}.story-light-wash{position:absolute;z-index:-2;inset:-12%;background:radial-gradient(ellipse at 72% 38%,rgba(183,247,216,.76),transparent 30%),radial-gradient(ellipse at 26% 24%,rgba(237,231,255,.95),transparent 37%),radial-gradient(ellipse at 52% 100%,rgba(77,168,255,.12),transparent 40%),#f8f9fc;animation:wash-drift 20s ease-in-out infinite alternate}.story-grain{position:absolute;z-index:4;inset:0;pointer-events:none;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='g'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.7' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23g)' opacity='.18'/%3E%3C/svg%3E")}.story-three{position:absolute;z-index:0;inset:0;overflow:hidden;pointer-events:none;opacity:.94}.story-three canvas{position:absolute;inset:0;display:block;width:100%;height:100%}.story-fallback-art{position:absolute;inset:0;display:grid;place-items:center;perspective:900px;transition:opacity .7s}.story-three.has-webgl .story-fallback-art{opacity:0}.fallback-sphere{position:absolute;width:min(32vw,330px);aspect-ratio:1;border-radius:38% 62% 58% 42%/46% 39% 61% 54%;background:radial-gradient(circle at 31% 24%,#fff 0 5%,#f2f1ff 11%,#c9baff 28%,#a8dbff 51%,#cefae4 70%,#fff 78%);box-shadow:inset -22px -24px 38px #71639a25,inset 12px 10px 25px #fff,0 35px 65px #8075a428,0 0 90px #b8a8ff30;animation:float-light 9s ease-in-out infinite}.fallback-ring{position:absolute;width:min(48vw,520px);height:min(18vw,175px);border:1px solid rgba(121,87,255,.32);border-radius:50%;box-shadow:0 0 35px rgba(121,87,255,.08);transform:rotate(-24deg);animation:ring-float 11s ease-in-out infinite}.fallback-ring.second{width:min(48vw,520px);height:min(12vw,120px);border-color:rgba(77,168,255,.3);transform:rotate(62deg);animation-delay:-3s}.fallback-star{position:absolute;top:27%;left:64%;color:#7957ff;font-size:24px;text-shadow:0 0 18px #fff;animation:slow-spin 18s linear infinite}.story-topbar{position:absolute;z-index:10;top:max(14px,env(safe-area-inset-top));right:max(22px,env(safe-area-inset-right));left:max(22px,env(safe-area-inset-left));display:grid;grid-template-columns:1fr auto 1fr;align-items:center;min-height:48px}.story-logo{display:flex;width:max-content;align-items:center;gap:9px;color:#252838;font-size:8px;font-weight:700;line-height:1.45;letter-spacing:.11em}.story-logo-glyph{font-size:30px;line-height:1;letter-spacing:-4px}.story-logo-glyph span{color:var(--violet)}.story-top-meta{display:flex;align-items:center;gap:8px;color:#697080;font:8px var(--mono);letter-spacing:.13em}.story-live-dot{width:6px;height:6px;border-radius:50%;background:#63cda2;box-shadow:0 0 0 4px rgba(99,205,162,.15)}.story-skip{justify-self:end;display:inline-flex;min-height:42px;align-items:center;gap:10px;padding:0 14px;border:1px solid rgba(23,25,35,.16);border-radius:99px;background:rgba(255,255,255,.54);color:#33384a;font:8px var(--mono);letter-spacing:.1em;transition:background .2s,transform .2s}.story-skip:hover{transform:translateY(-2px);background:#fff}.story-scenes{position:absolute;z-index:2;inset:83px 5.4vw 107px;overflow:hidden;touch-action:pan-y}.story-panel{position:absolute;inset:0;display:grid;place-items:center;overflow:auto;overscroll-behavior:contain;visibility:hidden;opacity:0;pointer-events:none;transform:translate3d(0,20px,0) scale(.99);transition:opacity .62s ease,transform .75s cubic-bezier(.18,.72,.2,1),visibility .65s}.story-panel.is-active{z-index:1;visibility:visible;opacity:1;pointer-events:auto;transform:none}.scene-content{position:relative;z-index:2;width:min(1040px,100%);max-height:100%;margin:auto;padding:20px 0;text-align:center}.scene-centered{display:flex;flex-direction:column;align-items:center;justify-content:center}.scene-kicker{margin:0 0 20px;color:#6d7180;font:9px var(--mono);letter-spacing:.16em}.story-title{max-width:100%;margin:0;color:#191b27;font-size:clamp(52px,8.2vw,112px);font-weight:600;line-height:.91;letter-spacing:-.075em}.story-title em{color:#7957ff;font-weight:400;font-style:normal}.violet-dot{color:var(--violet)}.story-subtitle{margin:20px 0 0;color:#36394a;font-size:clamp(12px,1.7vw,18px);font-weight:600;letter-spacing:.11em}.story-support{max-width:480px;margin:17px auto 0;color:#626b7a;font-size:14px;line-height:1.75}.scene-action{display:inline-flex;min-height:50px;align-items:center;gap:23px;margin-top:30px;padding:0 21px;border:0;border-radius:100px;background:#191b27;color:#fff;font:9px var(--mono);letter-spacing:.1em;box-shadow:0 12px 30px #48415c22;transition:transform .2s,background .2s}.scene-action:hover{transform:translateY(-3px);background:var(--violet)}.scene-action span{font-size:16px}.reveal-line{animation:line-reveal .8s .35s both}.story-brand-title{margin:0;color:#171923;font-size:clamp(56px,9vw,124px);font-weight:600;line-height:.78;letter-spacing:-.09em}.story-brand-title span{display:inline-block;margin-top:12px;color:#716b82;font-size:.38em;font-weight:400;letter-spacing:.025em}.story-tags{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin-top:27px}.story-tags span,.scene-categories span{padding:8px 11px;border:1px solid rgba(23,25,35,.12);border-radius:99px;background:rgba(255,255,255,.55);color:#596173;font:8px var(--mono);letter-spacing:.07em}.story-tags-wide{max-width:600px;margin-top:24px}.story-tags-wide span{background:rgba(255,255,255,.72)}.scene-gallery-content{display:flex;flex-direction:column;align-items:stretch;justify-content:center;text-align:left}.scene-gallery-content .scene-kicker{margin-bottom:12px}.compact-title{font-size:clamp(40px,5.4vw,69px)}.scene-categories{display:flex;flex-wrap:wrap;gap:7px;margin:17px 0 15px}.scene-categories span{padding:7px 9px;font-size:7px}.story-art-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:stretch}.story-art-card{position:relative;display:block;min-width:0;padding:0;border:0;border-radius:8px;background:#fff;text-align:left;box-shadow:0 15px 36px rgba(55,58,82,.09);overflow:hidden;transition:transform .28s,box-shadow .28s}.story-art-card:hover,.story-art-card:focus-visible{transform:translateY(-5px);box-shadow:0 22px 40px rgba(55,58,82,.15)}.story-art-card .project-art{height:clamp(112px,17vh,190px);min-height:100px}.story-art-card .project-meta{padding:9px 12px 11px}.story-art-card .project-title{font-size:12px}.story-art-card .project-number{font-size:6px}.scene-caption{margin:10px 0 0;color:#737a88;font:7px var(--mono);letter-spacing:.08em}.creator-layout{display:grid;grid-template-columns:minmax(190px,.7fr) 1fr;align-items:center;gap:clamp(30px,7vw,95px);text-align:left}.story-portrait{position:relative;justify-self:center;width:min(28vw,300px);height:min(43vh,390px);min-height:240px;overflow:hidden;border:1px solid #fff;border-radius:44% 44% 12px 12px;background:linear-gradient(155deg,#f1edff,#e8f9f1 75%);box-shadow:0 28px 65px rgba(84,88,124,.13)}.portrait-placeholder-label{position:absolute;z-index:2;top:14px;left:14px;padding:8px 10px;border:1px solid #fff;border-radius:4px;background:#ffffff9c;color:#626b7a;font:7px/1.5 var(--mono);letter-spacing:.1em}.story-portrait-silhouette{position:absolute;inset:20% 7% 0}.story-portrait-silhouette i{position:absolute;z-index:2;top:4%;left:36%;width:30%;height:34%;border-radius:46% 46% 43% 43%;background:linear-gradient(110deg,#e6d6cc,#b8a9a6 55%,#887e85);box-shadow:inset 8px 1px 12px #fff8}.story-portrait-silhouette b{position:absolute;bottom:-8%;left:7%;width:86%;height:68%;border-radius:47% 48% 0 0;background:linear-gradient(110deg,#ada4bf,#7f7b91 50%,#625e78);clip-path:polygon(30% 0,68% 0,85% 22%,100% 100%,0 100%,15% 22%)}.creator-copy{max-width:540px}.creator-copy .scene-kicker{margin-bottom:17px}.creator-title{font-size:clamp(54px,7vw,91px)}.creator-role{margin:14px 0 0;color:#5d6472;font:9px var(--mono);letter-spacing:.13em}.creator-copy .story-support{margin:15px 0 0}.creator-editable{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:19px}.creator-editable p{display:grid;gap:7px;margin:0;padding-top:10px;border-top:1px solid var(--line)}.creator-editable b{color:#7151ea;font:7px var(--mono);letter-spacing:.08em}.creator-editable span{color:#626b7a;font-size:10px;line-height:1.5}.portfolio-scene-content{display:flex;flex-direction:column;justify-content:center;text-align:left}.portfolio-scene-content>.scene-kicker{margin-bottom:10px}.portfolio-scene-heading{display:flex;align-items:end;justify-content:space-between;gap:20px}.portfolio-scene-heading>p{max-width:200px;margin:0 0 5px;color:#626b7a;font-size:10px;line-height:1.5}.story-filters{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.story-filter{min-height:31px;padding:0 11px;border:1px solid rgba(23,25,35,.13);border-radius:99px;background:#ffffff9c;color:#5a6070;font:7px var(--mono);letter-spacing:.03em}.story-filter[aria-pressed='true']{border-color:#7957ff;background:#7957ff;color:white}.story-project-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.story-project-card{position:relative;min-width:0}.story-project-grid .story-art-card .project-art{height:clamp(105px,15vh,157px)}.story-project-grid .story-art-card .project-meta{padding:8px 10px}.story-project-grid .story-art-card .project-title{font-size:11px}.story-project-grid .concept-flag{top:7px;right:7px;padding:5px;font-size:5px}.finale-content{display:flex;flex-direction:column;align-items:center;justify-content:center}.finale-title{font-size:clamp(47px,7.4vw,96px)}.final-actions{display:flex;justify-content:center;flex-wrap:wrap;gap:9px;margin-top:25px}.final-button{display:inline-flex;min-height:46px;align-items:center;justify-content:center;gap:13px;padding:0 15px;border:1px solid rgba(23,25,35,.16);border-radius:99px;background:#ffffffa6;color:#292c3a;font:8px var(--mono);letter-spacing:.06em;transition:transform .2s,background .2s}.final-button:hover{transform:translateY(-2px);background:white}.final-button.primary{border-color:#7957ff;background:#7957ff;color:#fff}.final-button.primary:hover{background:#6643f2}.story-contact-notice{min-height:15px;margin:10px 0 0;color:#714ee9;font:8px var(--mono)}.replay-story-end{border:0;background:none;color:#6b7180;font:8px var(--mono);letter-spacing:.08em}.story-controls{position:absolute;z-index:12;right:max(30px,env(safe-area-inset-right));bottom:max(22px,env(safe-area-inset-bottom));left:max(30px,env(safe-area-inset-left));display:grid;grid-template-columns:1fr minmax(180px,420px) 1fr;align-items:center;gap:20px}.story-control{display:inline-flex;min-width:108px;min-height:48px;align-items:center;justify-content:center;gap:10px;padding:0 15px;border:1px solid rgba(23,25,35,.16);border-radius:99px;background:#ffffffa8;color:#2c3040;font:8px var(--mono);letter-spacing:.09em;transition:background .2s,transform .2s}.story-control:hover{transform:translateY(-2px);background:#fff}.story-control span:first-child{font-size:16px}.story-back{grid-column:1;justify-self:start}.story-progress-wrap{grid-column:2}.story-next{grid-column:3;justify-self:end;border-color:#181a26;background:#181a26;color:white}.story-next:hover{background:var(--violet);border-color:var(--violet)}.story-progress-wrap{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:14px}.story-scene-count{white-space:nowrap;color:#737987;font:9px var(--mono)}.story-scene-count b{color:#202332;font-size:13px}.story-progress-track{display:grid;grid-template-columns:repeat(8,1fr);gap:5px}.story-progress-segment{height:3px;border-radius:3px;background:rgba(23,25,35,.14);overflow:hidden}.story-progress-segment i{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--violet),var(--blue));transition:width .45s ease}.story-progress-segment.is-done i,.story-progress-segment.is-current i{width:100%}
/* Controlled visual states for the eight story beats (also the no-WebGL fallback). */
.storyboard[data-scene='0'] .fallback-sphere{width:120px;animation:spark-grow 1.2s .2s cubic-bezier(.2,.7,.2,1) both,float-light 9s 1.4s ease-in-out infinite}.storyboard[data-scene='1'] .fallback-sphere{width:min(39vw,390px);border-radius:32% 68% 57% 43%;filter:saturate(1.2)}.storyboard[data-scene='2'] .fallback-ring{width:min(52vw,570px);height:min(31vw,285px);border-width:2px;transform:rotate(-5deg) scaleY(1.2)}.storyboard[data-scene='3'] .fallback-ring{width:min(43vw,440px);height:min(26vw,230px);transform:rotate(-15deg) scaleY(1.18)}.storyboard[data-scene='4'] .fallback-sphere{width:min(28vw,290px);border-radius:44% 56% 42% 58%;filter:hue-rotate(20deg)}.storyboard[data-scene='5'] .fallback-ring{width:min(39vw,390px);height:min(39vw,390px);border-radius:32%;transform:rotate(35deg)}.storyboard[data-scene='6'] .fallback-ring{width:min(55vw,600px);height:min(23vw,210px);transform:rotate(4deg)}.storyboard[data-scene='7'] .fallback-sphere{width:min(37vw,380px);box-shadow:inset -22px -24px 38px #71639a25,inset 12px 10px 25px #fff,0 35px 65px #8075a428,0 0 120px #b8a8ff66}.story-skip,.story-control,.scene-action,.final-button,.story-filter,.story-art-card,.replay-story-end,.replay-story-nav,.mobile-replay-story{touch-action:manipulation}.story-art-gallery,.story-project-grid{touch-action:pan-x pan-y}
/* Blogger page: responsive, light surfaces and no desktop-only fixed widths. */
.site-content{width:100%;min-height:100vh;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .75s ease,visibility .75s}.site-content.is-revealed{opacity:1;visibility:visible;pointer-events:auto}.site-content[aria-hidden='true']{user-select:none}.scroll-progress{position:fixed;z-index:80;top:0;left:0;width:100%;height:2px;background:linear-gradient(90deg,var(--violet),var(--blue));transform:scaleX(0);transform-origin:left;pointer-events:none}.site-header{position:sticky;z-index:50;top:0;display:flex;width:100%;height:74px;align-items:center;justify-content:space-between;padding:0 clamp(20px,5vw,74px);border-bottom:1px solid rgba(23,25,35,.06);background:rgba(248,249,252,.88);backdrop-filter:blur(16px)}.wordmark{display:flex;min-width:160px;align-items:center;gap:9px}.wordmark-icon{font-size:31px;font-weight:700;line-height:1;letter-spacing:-4px}.wordmark-icon span{color:var(--violet)}.wordmark-name{font-size:8px;font-weight:700;line-height:1.4;letter-spacing:.12em}.desktop-nav{display:flex;align-items:center;gap:clamp(15px,2.5vw,36px)}.desktop-nav>a,.replay-story-nav,.sound-toggle{color:#434a59;font:8px var(--mono);letter-spacing:.08em}.desktop-nav a:hover,.replay-story-nav:hover{color:var(--violet)}.nav-contact{display:flex;align-items:center;gap:4px}.skip-intro{color:#5951a2!important}.replay-story-nav{padding:8px 0;border:0;background:none}.sound-toggle{display:flex;align-items:center;gap:6px;padding:8px 0;border:0;background:none}.sound-state{width:5px;height:5px;border-radius:50%;background:#aeb3bf}.sound-toggle[aria-pressed='true'] .sound-state{background:var(--violet);box-shadow:0 0 8px #7957ff66}.sound-icon{color:#5951a2}.mobile-actions,.menu-toggle,.mobile-menu{display:none}.hero{position:relative;display:grid;min-height:min(780px,calc(100svh - 74px));min-height:min(780px,calc(100dvh - 74px));align-items:center;overflow:hidden;padding:100px clamp(22px,10vw,150px);background:radial-gradient(ellipse at 75% 42%,#d9f8ee 0,transparent 29%),radial-