body.script:
//
(function(){
  'use strict';
  /* Owner-editable brand and contact details. Keep contact fields empty until confirmed. */
  var STUDIO_CONFIG={name:'SINGH CREATIVE STUDIO',founder:'Mukesh Singh',whatsapp:'',email:'',instagram:'https://www.instagram.com/YOUR_HANDLE/',behance:'https://www.behance.net/YOUR_HANDLE'};
  /* Demonstration concepts only. Replace image/video values with public HTTPS assets when supplied. */
  var PROJECTS=[
    {id:'form-study-01',title:'Form Study No. 01',category:'3D Animation',number:'01',description:'A study in balance, reflection and quiet movement. Polished material forms meet an atmospheric field of light.',visual:'orb',label:'3D / CONCEPT STUDY',process:'An exploration of material, silhouette and light for a future motion piece.',image:'',video:''},
    {id:'afterimage',title:'Afterimage',category:'Graphic Design',number:'02',description:'A typographic experiment about the persistence of a fleeting thought.',visual:'type',label:'TYPE / CONCEPT STUDY',process:'Expressive letterforms, paper-like grain and a limited palette bring an abstract idea into focus.',image:'',video:''},
    {id:'soft-geometry',title:'Soft Geometry',category:'Brand Identity',number:'03',description:'A visual identity direction exploring the tension between precision and softness.',visual:'geo',label:'IDENTITY / CONCEPT STUDY',process:'A flexible graphic language built from repeating forms, considered spacing and restrained colour.',image:'',video:''},
    {id:'light-matter',title:'Light / Matter',category:'Motion Graphics',number:'04',description:'An imagined motion-design frame where light behaves like a sculptural material.',visual:'light',label:'MOTION / CONCEPT STUDY',process:'A visual study in contrast, luminous colour and dimensional composition.',image:'',video:''},
    {id:'object-orbit',title:'Object in Orbit',category:'3D Animation',number:'05',description:'A sculptural object suspended between industrial design and the impossible.',visual:'orbit',label:'3D / CONCEPT STUDY',process:'An exploratory CGI still concept. This artwork is not a video.',image:'',video:''},
    {id:'signal-form',title:'Signal / Form',category:'Graphic Design',number:'06',description:'An editorial poster concept built around rhythm, signal and a strong focal point.',visual:'poster',label:'POSTER / CONCEPT STUDY',process:'Large-scale type and a vivid form create visual impact across a minimal layout.',image:'',video:''}
  ];
  var FILTERS=['All Projects','Graphic Design','3D Animation','Motion Graphics','Branding'];
